    <script>function menuSortable(){return{sortables:[],initSortable(){this.destroySortables();document.querySelectorAll('.menu-list').forEach((element)=>{this.sortables.push(new Sortable(element,{group:'nested',animation:150,fallbackOnBody:true,swapThreshold:.65,handle:'.drag-handle',ghostClass:'menu-sortable-ghost',chosenClass:'menu-sortable-chosen',onEnd:()=>this.saveOrder()}))})},destroySortables(){this.sortables.forEach((sortable)=>sortable.destroy());this.sortables=[]},saveOrder(){const getIds=(root)=>Array.from(root.children).filter((element)=>element.tagName==='LI').map((element)=>{const item={id:element.getAttribute('data-id')};const childList=element.querySelector(':scope > ul');if(childList&&childList.children.length>0)item.children=getIds(childList);return item});const rootList=document.getElementById('root-menu-list');if(rootList)@this.updateMenuOrder(getIds(rootList))}}}</script>
</div>
